/** CSS completo dell'identità (font + token + componenti + motion + condiviso). */
export function designCss(theme: ThemeName): string {
  if (theme === 'athletic-premium') return FONTS_ATHLETIC + ATHLETIC_CSS + SHARED_MEDIA + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'scandinavian-service') return FONTS_SCANDI + SCANDI_CSS + SHARED_MEDIA + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'warm-bistro') return FONTS_BISTRO + BISTRO_CSS + SHARED_MEDIA + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'modern-saas') return FONTS_SAAS + SAAS_CSS + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'creative-studio') return FONTS_CREATIVE + CREATIVE_CSS + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'future-minimal') return FONTS_FUTURE + FUTURE_CSS + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'modern-community') return FONTS_COMMUNITY + COMMUNITY_CSS + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  if (theme === 'industrial-bold') return FONTS_INDUSTRIAL + INDUSTRIAL_CSS + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD;
  return FONTS_EDITORIAL + TOKENS_EDITORIAL + COMPONENTS_EDITORIAL + SHARED_MEDIA + PIZZERIA_SIGNATURE_CSS + FORM_CSS + OVERFLOW_GUARD + MOTION_CSS;
}

const STYLE_RE = /<style data-brik-ds[^>]*>[\s\S]*?<\/style>/i;
const SCRIPT_RE = /<script data-brik-motion[^>]*>[\s\S]*?<\/script>/i;
const DIR_ATTR_RE = /(<html\b[^>]*?)\s+data-brik-dir="[^"]*"/i;
const VARIANT_ATTR_RE = /(<html\b[^>]*?)\s+data-brik-variant="[^"]*"/i;

/** Inietta stile + motion nel <head> di ogni pagina (lo script aggiunge brik-anim prima del paint → no flash). */
export function injectDesignSystem(
  pages: readonly { route: string; html: string }[],
  theme: ThemeName,
  variant?: string,
): { route: string; html: string }[] {
  const style = '<style data-brik-ds="' + theme + '">' + designCss(theme) + '</style>';
  const script = '<script data-brik-motion>' + MOTION_JS + '</script>';
  const block = style + script;
  return pages.map((p) => {
    const prev = p.html.match(/<html\b[^>]*?\sdata-brik-variant="([a-z-]+)"/i);
    const v = (variant === 'dark' || variant === 'light') ? variant : (prev ? prev[1] : undefined);
    const attrs = ' data-brik-dir="' + theme + '"' + (v ? ' data-brik-variant="' + v + '"' : '');
    let html = p.html.replace(STYLE_RE, '').replace(SCRIPT_RE, '');
    html = html.replace(DIR_ATTR_RE, '$1').replace(VARIANT_ATTR_RE, '$1');
    if (/<html\b/i.test(html)) html = html.replace(/<html\b/i, '<html' + attrs);
    if (/<\/head>/i.test(html)) html = html.replace(/<\/head>/i, block + '</head>');
    else if (/<body[^>]*>/i.test(html)) html = html.replace(/<body[^>]*>/i, (mm) => mm + block);
    else html = block + html;
    return { route: p.route, html };
  });
}

/** Rimuove il blocco del design system (per rigenerare in modo pulito). */
export function deInjectDesignSystem(
  pages: readonly { route: string; html: string }[],
): { route: string; html: string }[] {
  return pages.map((p) => ({ route: p.route, html: p.html.replace(STYLE_RE, '').replace(SCRIPT_RE, '').replace(DIR_ATTR_RE, '$1') }));
}

/** Legge il tema usato dalle pagine correnti (fallback al default se sconosciuto). */
export function variantOfPages(pages: readonly { route: string; html: string }[]): string {
  for (const p of pages) {
    const mm = p.html.match(/<html\b[^>]*?\sdata-brik-variant="([a-z-]+)"/i);
    if (mm) return mm[1]!;
  }
  return 'light';
}

export function themeOfPages(pages: readonly { route: string; html: string }[]): ThemeName {
  for (const p of pages) {
    const mm = p.html.match(/<style data-brik-ds="([a-z-]+)"/i);
    if (mm && isTheme(mm[1]!)) return mm[1] as ThemeName;
  }
  return DEFAULT_THEME;
}
